package quebec.culture.donnees;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;
public class TeamCapacityActivity extends Activity{private SharedPreferences p;private final String[] keys={"chef","data","tech","competences","partenaires","fournisseurs","gouvernance","continuite","formation"};private final String[] labels={"Responsable du projet","Responsable des données","Responsable technique","Compétences et expérience de l’équipe","Partenaires","Sous-traitants / fournisseurs","Gouvernance et décisions","Continuité après la subvention","Besoins de formation"};private EditText[] fields=new EditText[keys.length];@Override public void onCreate(Bundle b){super.onCreate(b);Ui.bars(this);p=getSharedPreferences("team_capacity",0);LinearLayout r=Ui.root(this);r.addView(Ui.text(this,"Équipe et capacité de réalisation",27,true));r.addView(Ui.text(this,"Documenter qui réalise la mise à niveau, les compétences disponibles, les partenaires et la continuité du projet.",14,false));for(int i=0;i<keys.length;i++){fields[i]=Ui.field(this,labels[i],p.getString(keys[i],""));r.addView(fields[i]);}Button s=Ui.primary(this,"Enregistrer");s.setOnClickListener(v->{SharedPreferences.Editor e=p.edit();for(int i=0;i<keys.length;i++)e.putString(keys[i],fields[i].getText().toString());e.apply();Toast.makeText(this,"Équipe enregistrée",Toast.LENGTH_SHORT).show();});r.addView(s);Button risk=Ui.secondary(this,"Ouvrir le registre des risques");risk.setOnClickListener(v->startActivity(new Intent(this,RiskRegisterActivity.class)));r.addView(risk);setContentView(Ui.wrap(this,r));}}
